import json
d=json.load(open('hig.json'))
def walk(n,out):
    if isinstance(n,dict):
        if n.get('type')=='text': out.append(n['text'])
        elif n.get('type')=='heading': out.append('\n## '+n.get('text','')+'\n')
        elif n.get('type')=='paragraph': out.append('\n')
        elif n.get('type')=='reference': out.append('['+n.get('identifier','').split('/')[-1]+']')
        for v in n.values(): walk(v,out)
    elif isinstance(n,list):
        for v in n: walk(v,out)
out=[]
walk(d.get('primaryContentSections',[]),out)
print(''.join(out))
print('=====TOPIC SECTIONS=====')
for ts in d.get('topicSections',[]):
    print('##',ts.get('title'))
    print(' ',', '.join(i.split('/')[-1] for i in ts.get('identifiers',[])))
"

